var shapes = [];
var e = new p5.Ease();
var ox, oy;
var img = [];

function preload() {
	for (let i = 0; i < 10; i++) {
		img[i] = loadImage(nf(i, 2) + ".png");
	}
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	// imageMode(CENTER);

	ox = width / 2;
	oy = height / 2;

	angleMode(DEGREES);
}

function draw() {
	background(255);

	shapes.push(new Shape(ox, oy));
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		shapes.push(new Shape((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-30, 30), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-30, 30)));
	}

	for (let i = 0; i < shapes.length; i++) {
		shapes[i].display();
	}

	ox += random(-45, 45);
	oy += random(-45, 45);

	if (ox > width) {
		ox = width;
	}
	if (ox < 0) {
		ox = 0;
	}
	if (oy > height) {
		oy = height;
	}
	if (oy < 0) {
		oy = 0;
	}

	for (let j = 0; j < shapes.length; j++) {
		if (shapes[j].isFinished) {
			shapes.splice(j, 1);
		}
	}
}

function Shape(tmpX, tmpY) {
	this.pos = createVector(tmpX, tmpY);
	this.rMax = random(0.1, 1.0);
	this.theta = random(360);
	this.r = 0;
	this.delta = 0;
	this.speed = 1 / 100;
	this.isDeg = false;
	this.isFinished = false;
	this.imgIndex = floor(random(img.length));

	this.display = function () {
		if (!this.isDeg) {
			this.r = this.rMax * e.quarticOut(this.delta);

			this.delta += this.speed;
			if (this.delta > 1.0) {
				this.delta = 1.0;
				this.isDeg = true;
			}
		} else {
			this.r = this.rMax * e.quarticOut(this.delta);

			this.delta -= this.speed * 0.75;
			if (this.delta < 0.0) {
				this.delta = 0.0;
				this.isFinished = true;
			}
		}

		push();
		translate(this.pos.x, this.pos.y);
		rotate(this.theta);
		scale(this.r);

		image(img[this.imgIndex], 0, 0);
		pop();
	}
}
